package shop.msavdo.admin;
import android.app.*; import android.graphics.Color; import android.os.*; import android.text.InputType; import android.view.*; import android.webkit.*; import android.widget.*; import org.json.*; import java.io.*; import java.net.*; import java.nio.charset.StandardCharsets; import java.util.*; import java.util.concurrent.*;
public final class MainActivity extends Activity {
 static final String ADMIN="https://msavdo.shop/?mobile-admin=1", API="https://api.msavdo.shop/api/parse-product-html", ORIGIN="https://api.msavdo.shop";
 final Handler main=new Handler(Looper.getMainLooper()); final ExecutorService work=Executors.newSingleThreadExecutor(); final Queue<String> links=new ArrayDeque<>(); WebView web; TextView status; Button next; boolean automatic;
 @Override public void onCreate(Bundle b){super.onCreate(b); android.webkit.CookieManager.getInstance().setAcceptCookie(true); LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL); LinearLayout bar=new LinearLayout(this);bar.setBackgroundColor(Color.rgb(17,24,39));
  Button admin=button("Admin"),importer=button("Import 1688");next=button("Next");next.setEnabled(false);bar.addView(admin,new LinearLayout.LayoutParams(0,dp(44),1));bar.addView(importer,new LinearLayout.LayoutParams(0,dp(44),1));bar.addView(next,new LinearLayout.LayoutParams(0,dp(44),.7f));root.addView(bar);status=new TextView(this);status.setText("Ready");status.setTextSize(12);status.setPadding(dp(8),0,dp(8),0);root.addView(status,new LinearLayout.LayoutParams(-1,dp(26)));
  web=new WebView(this);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setSupportMultipleWindows(true);s.setJavaScriptCanOpenWindowsAutomatically(true);web.addJavascriptInterface(new Bridge(),"MSavdoMobile");web.setWebChromeClient(new WebChromeClient());web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){String p=r.getUrl().getScheme();return !("http".equalsIgnoreCase(p)||"https".equalsIgnoreCase(p));}@Override public void onPageFinished(WebView v,String url){if(market(url)){status.setText("Product page ready");main.postDelayed(()->inject(),1800);if(automatic&&!links.isEmpty())main.postDelayed(()->capture(),4000);}}});root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);admin.setOnClickListener(v->web.loadUrl(ADMIN));importer.setOnClickListener(v->queueDialog());next.setOnClickListener(v->openNext());web.loadUrl(ADMIN); }
 int dp(int n){return(int)(n*getResources().getDisplayMetrics().density);} Button button(String t){Button b=new Button(this);b.setText(t);b.setTextSize(12);b.setAllCaps(false);b.setTextColor(Color.DKGRAY);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(245,197,66)));return b;}
 boolean market(String x){try{String h=new URL(x).getHost().toLowerCase(Locale.ROOT);return h.equals("1688.com")||h.endsWith(".1688.com")||h.equals("taobao.com")||h.endsWith(".taobao.com")||h.equals("tmall.com")||h.endsWith(".tmall.com")||h.equals("alibaba.com")||h.endsWith(".alibaba.com");}catch(Exception e){return false;}}
 void queueDialog(){EditText e=new EditText(this);e.setHint("1688 links, one per line");e.setMinLines(5);e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);new AlertDialog.Builder(this).setTitle("Mass import").setMessage("Open each product and save it as a draft.").setView(e).setNegativeButton("Cancel",null).setPositiveButton("Start",(d,w)->{links.clear();for(String line:e.getText().toString().split("[\\r\\n,;]+")){String u=line.trim();if(market(u))links.add(u);}automatic=!links.isEmpty();next.setEnabled(automatic);if(automatic)openNext();else toast("No valid links");}).show();}
 void openNext(){String u=links.peek();if(u==null){automatic=false;next.setEnabled(false);status.setText("Queue complete");return;}status.setText("Opening product ? "+links.size()+" left");web.loadUrl(u);}
 void inject(){web.evaluateJavascript("(function(){if(document.getElementById('msavdo-import'))return;var b=document.createElement('button');b.id='msavdo-import';b.textContent='Add to MSavdo';b.style='position:fixed;z-index:999999;bottom:20px;right:16px;padding:14px 18px;border:0;border-radius:14px;background:#f5c542;color:#111;font:bold 15px sans-serif;box-shadow:0 4px 18px #0005';b.onclick=function(){b.textContent='Saving...';MSavdoMobile.capture(JSON.stringify({url:location.href,title:document.title,html:document.documentElement.outerHTML}));};document.body.appendChild(b);})();",null);}
 void capture(){web.evaluateJavascript("JSON.stringify({url:location.href,title:document.title,html:document.documentElement.outerHTML})",v->{try{new Bridge().capture(new JSONArray("["+v+"]").getString(0));}catch(Exception e){toast("Cannot read product page");}});}
 final class Bridge{@JavascriptInterface public void capture(String text){try{JSONObject p=new JSONObject(text);work.execute(()->send(p));}catch(Exception e){toast("Cannot read product page");}}}
 void send(JSONObject p){HttpURLConnection c=null;try{String html=p.optString("html","");String cookie=android.webkit.CookieManager.getInstance().getCookie(ORIGIN);if(html.length()<10||html.length()>2000000)throw new Exception("Page is empty or too large");if(cookie==null||!cookie.contains("__Host-msavdo_admin="))throw new Exception("Login with Telegram in Admin first");JSONObject b=new JSONObject();b.put("html_code",html);b.put("original_link",p.optString("url",""));b.put("manual_title",p.optString("title",""));b.put("weight_kg",0.5);b.put("delivery_type","order");b.put("save_to_catalog",true);c=(HttpURLConnection)new URL(API).openConnection();c.setRequestMethod("POST");c.setConnectTimeout(20000);c.setReadTimeout(90000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Cookie",cookie);byte[] data=b.toString().getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(data.length);try(OutputStream o=c.getOutputStream()){o.write(data);}int code=c.getResponseCode();InputStream in=code>=400?c.getErrorStream():c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);JSONObject r=new JSONObject(out.toString("UTF-8"));if(code<200||code>=300||!r.optBoolean("success"))throw new Exception(r.optString("error",r.optString("message","Import failed")));String title=r.optJSONObject("product")==null?"Draft":r.optJSONObject("product").optString("title","Draft");main.post(()->{toast("Draft saved: "+title);status.setText("Draft saved");links.poll();next.setEnabled(!links.isEmpty());if(!links.isEmpty())main.postDelayed(this::openNext,1200);else automatic=false;});}catch(Exception e){main.post(()->{status.setText(e.getMessage());toast(e.getMessage());automatic=false;});}finally{if(c!=null)c.disconnect();}}
 void toast(String s){main.post(()->Toast.makeText(this,s,Toast.LENGTH_LONG).show());}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}@Override protected void onDestroy(){work.shutdownNow();web.destroy();super.onDestroy();}
}
